/*
 * ======================================================
 * CHAMBER PROCESS ANALYZER V2
 * Sterilization sebagai proses utama
 * ======================================================
 *
 * STATE:
 * IDLE
 * HEATING
 * STERILIZATION
 * COOLING
 * FINISH
 * FAILED
 *
 * ======================================================
 * RULES
 * ======================================================
 *
 * START CYCLE       : T >= 35 C setelah IDLE
 * ENTER STERI       : T >= 117 C
 * STERI VALID       : 117 C <= T <= 121 C
 * HOLD REQUIRED     : 16 menit
 * STERI TIMEOUT     : 25 menit
 * COOLING COMPLETE  : T <= 35 C selama 5 menit
 *
 * Catatan:
 * dT/dt hanya digunakan sebagai informasi diagnostik.
 * Tidak digunakan sebagai failure hanya karena satu titik
 * temperature mengalami penurunan.
 */

const c = msg.chamber;

if (!c) {
    node.error("msg.chamber tidak ditemukan");
    return null;
}

const PROJECT_CODE = c.project_code;
const SENSOR_CODE = c.sensor_code;
const temperature = Number(c.temperature);

let timestamp = new Date(c.timestamp);

if (isNaN(timestamp.getTime())) {
    timestamp = new Date();
}

// ======================================================
// CONFIGURATION
// ======================================================

const START_TEMP = 35;

const STERI_MIN = 117;
const STERI_MAX = 121;

const STERI_HOLD_SEC = 16 * 60;
const STERI_TIMEOUT_SEC = 25 * 60;

const HEATING_TIMEOUT_SEC = 25 * 60;

const COOLING_COMPLETE_TEMP = 35;
const COOLING_STABLE_SEC = 5 * 60;

// ======================================================
// DATE / TIME
// ======================================================

function pad(n) {
    return String(n).padStart(2, "0");
}

const productionDate =
    timestamp.getFullYear() + "-" +
    pad(timestamp.getMonth() + 1) + "-" +
    pad(timestamp.getDate());

const timeOnly =
    pad(timestamp.getHours()) + ":" +
    pad(timestamp.getMinutes()) + ":" +
    pad(timestamp.getSeconds());

// ======================================================
// CONTEXT KEY
// ======================================================

const contextKey =
    "chamber_state_" +
    PROJECT_CODE + "_" +
    SENSOR_CODE;

let state = flow.get(contextKey);

if (!state) {
    state = {
        state: "IDLE",
        cycle: null,
        production_date: null,
        cycle_start: null,
        cycle_end: null,
        heating_start: null,
        sterilization_start: null,
        cooling_start: null,
        last_timestamp: null,
        last_temperature: null,
        valid_holding_sec: 0,
        sterilization_duration_sec: 0,
        heating_duration_sec: 0,
        cooling_duration_sec: 0,
        cooling_below_since: null,
        warning_code: null,
        warning: null,
        last_rate: 0
    };
}

// ======================================================
// HELPER
// ======================================================

function durationSec(start, end) {
    if (!start) return 0;

    return Math.max(
        0,
        (new Date(end).getTime() - new Date(start).getTime()) / 1000
    );
}

function setWarning(code, message) {
    state.warning_code = code;
    state.warning = message;
}

function clearWarning() {
    state.warning_code = null;
    state.warning = null;
}

function sqlEscape(value) {
    if (value === null || value === undefined) {
        return "NULL";
    }

    return "'" + String(value)
        .replace(/\\/g, "\\\\")
        .replace(/'/g, "''") + "'";
}

// ======================================================
// DAILY RESET
// ======================================================

if (
    state.production_date &&
    state.production_date !== productionDate &&
    state.state === "IDLE"
) {
    state.cycle = null;
    state.production_date = productionDate;
}

// ======================================================
// dT/dt
// ======================================================

let rate = 0;

if (state.last_timestamp && state.last_temperature !== null) {

    const currentMs = timestamp.getTime();
    const previousMs = new Date(state.last_timestamp).getTime();

    const deltaSec = (currentMs - previousMs) / 1000;

    if (deltaSec > 0) {
        rate =
            ((temperature - state.last_temperature) / deltaSec) * 60;
    }
}

state.last_rate = rate;

// ======================================================
// STATE MACHINE
// ======================================================

switch (state.state) {

    // ==================================================
    // IDLE
    // ==================================================

    case "IDLE": {

        /*
         * Cycle baru dimulai ketika temperature
         * keluar dari kondisi ambient.
         *
         * Tidak menggunakan dT/dt sebagai syarat wajib.
         */

        if (temperature >= START_TEMP) {

            // Reset cycle jika production date berubah
            if (state.production_date !== productionDate) {
                state.cycle = null;
            }

            state.cycle = (Number(state.cycle) || 0) + 1;
            state.production_date = productionDate;

            state.cycle_start = timestamp.toISOString();
            state.cycle_end = null;

            state.heating_start = timestamp.toISOString();
            state.sterilization_start = null;
            state.cooling_start = null;

            state.valid_holding_sec = 0;
            state.sterilization_duration_sec = 0;
            state.heating_duration_sec = 0;
            state.cooling_duration_sec = 0;
            state.cooling_below_since = null;

            clearWarning();

            state.state = "HEATING";

            node.status({
                fill: "blue",
                shape: "dot",
                text: "Cycle " + state.cycle + " - HEATING"
            });
        }

        break;
    }

    // ==================================================
    // HEATING
    // ==================================================

    case "HEATING": {

        state.heating_duration_sec = durationSec(
            state.heating_start,
            timestamp
        );

        /*
         * Sterilization dianggap dimulai ketika
         * temperature pertama kali masuk >=117 C.
         */

        if (temperature >= STERI_MIN) {

            state.state = "STERILIZATION";
            state.sterilization_start = timestamp.toISOString();
            state.valid_holding_sec = 0;

            clearWarning();

            node.status({
                fill: "green",
                shape: "dot",
                text: "Cycle " + state.cycle + " - STERILIZATION"
            });
        }

        /*
         * Heating timeout.
         */
        else if (state.heating_duration_sec >= HEATING_TIMEOUT_SEC) {

            setWarning(
                "HEATING_TIMEOUT",
                "Temperature belum mencapai 117 C dalam 25 menit"
            );

            state.state = "FAILED";

            node.status({
                fill: "red",
                shape: "dot",
                text: "Cycle " + state.cycle + " - FAILED"
            });
        }

        break;
    }

    // ==================================================
    // STERILIZATION
    // ==================================================

    case "STERILIZATION": {

        state.sterilization_duration_sec = durationSec(
            state.sterilization_start,
            timestamp
        );

        // ----------------------------------------------
        // TEMPERATURE VALID
        // ----------------------------------------------

        if (
            temperature >= STERI_MIN &&
            temperature <= STERI_MAX
        ) {

            /*
             * Tambahkan interval hanya jika sample
             * sebelumnya juga berada di range valid.
             *
             * Ini mencegah lonjakan waktu holding
             * saat ada gap data.
             */

            if (
                state.last_timestamp &&
                state.last_temperature !== null &&
                state.last_temperature >= STERI_MIN &&
                state.last_temperature <= STERI_MAX
            ) {

                const deltaSec =
                    (timestamp.getTime() -
                    new Date(state.last_timestamp).getTime()) / 1000;

                // Hindari gap besar dihitung sebagai holding
                if (deltaSec > 0 && deltaSec <= 120) {
                    state.valid_holding_sec += deltaSec;
                }
            }

            clearWarning();
        }

        // ----------------------------------------------
        // TEMPERATURE LOW
        // ----------------------------------------------

        else if (temperature < STERI_MIN) {

            setWarning(
                "STERI_TEMP_LOW",
                "Temperature sterilization di bawah 117 C"
            );

            /*
             * HOLDING PAUSE.
             * Tidak reset ke 0.
             */
        }

        // ----------------------------------------------
        // TEMPERATURE HIGH
        // ----------------------------------------------

        else if (temperature > STERI_MAX) {

            setWarning(
                "STERI_TEMP_HIGH",
                "Temperature sterilization di atas 121 C"
            );
        }

        // ----------------------------------------------
        // HOLDING COMPLETE
        // ----------------------------------------------

        if (state.valid_holding_sec >= STERI_HOLD_SEC) {

            state.state = "COOLING";
            state.cooling_start = timestamp.toISOString();
            state.cooling_below_since = null;

            clearWarning();

            node.status({
                fill: "green",
                shape: "dot",
                text: "Cycle " + state.cycle + " - COOLING"
            });
        }

        // ----------------------------------------------
        // STERILIZATION TIMEOUT
        // ----------------------------------------------

        else if (
            state.sterilization_duration_sec >=
            STERI_TIMEOUT_SEC
        ) {

            setWarning(
                "STERI_HOLD_TIMEOUT",
                "Holding valid belum mencapai 16 menit dalam 25 menit"
            );

            state.state = "FAILED";

            node.status({
                fill: "red",
                shape: "dot",
                text: "Cycle " + state.cycle + " - FAILED"
            });
        }

        break;
    }

    // ==================================================
    // COOLING
    // ==================================================

    case "COOLING": {

        state.cooling_duration_sec = durationSec(
            state.cooling_start,
            timestamp
        );

        /*
         * Jangan langsung selesai hanya karena satu
         * sample <35 C.
         */

        if (temperature <= COOLING_COMPLETE_TEMP) {

            if (!state.cooling_below_since) {
                state.cooling_below_since = timestamp.toISOString();
            }

            const stableDuration = durationSec(
                state.cooling_below_since,
                timestamp
            );

            if (stableDuration >= COOLING_STABLE_SEC) {

                state.state = "FINISH";
                state.cycle_end = timestamp.toISOString();

                clearWarning();

                node.status({
                    fill: "green",
                    shape: "dot",
                    text: "Cycle " + state.cycle + " - FINISH"
                });
            }
        }
        else {
            // Temperature kembali naik, timer stabil di-reset.
            state.cooling_below_since = null;
        }

        break;
    }

    // ==================================================
    // FINISH
    // ==================================================

    case "FINISH": {

        /*
         * Cycle sudah selesai.
         * Tetap FINISH sampai sample berikutnya,
         * kemudian kembali IDLE.
         */

        state.state = "IDLE";

        node.status({
            fill: "grey",
            shape: "ring",
            text: "Cycle " + state.cycle + " selesai"
        });

        break;
    }

    // ==================================================
    // FAILED
    // ==================================================

    case "FAILED": {

        /*
         * Cycle gagal tetap dipertahankan sampai
         * chamber kembali ke kondisi rendah.
         *
         * Setelah <=35 C, cycle ditutup.
         */

        if (temperature <= COOLING_COMPLETE_TEMP) {

            if (!state.cooling_below_since) {
                state.cooling_below_since = timestamp.toISOString();
            }

            const stableDuration = durationSec(
                state.cooling_below_since,
                timestamp
            );

            if (stableDuration >= COOLING_STABLE_SEC) {

                state.cycle_end = timestamp.toISOString();
                state.state = "FINISH";

                node.status({
                    fill: "red",
                    shape: "dot",
                    text: "Cycle " + state.cycle + " FAILED"
                });
            }
        }
        else {
            state.cooling_below_since = null;
        }

        break;
    }
}

