        durasi_menit: durationMin,
        avg_arus: Number(finalAvg),
        eval_summary: finalStatus,
        v_min: std.v_min, v_max: std.v_max,
        i_min: std.i_min, i_max: std.i_max,
        f_min: std.f_min, f_max: std.f_max
    });

    let ccpUuid = msg.ccp?.uuid || msg.ccp_uuid || "674ad6bf-7d58-407f-9f87-8f4f3d2afe92";

    // Update kolom 'end' dan data final
    let sql = `
        INSERT INTO sensor_cycle 
        (project_code, sensor_code, production_date, cycle, start, end, status, data)
        VALUES 
        ('${ccpUuid}', 'STUNNER_SUMMARY', CURDATE(), '${truckId}', '${startTime}', '${endTime}', '${finalStatus}', '${jsonData}')
        ON DUPLICATE KEY UPDATE 
        end=VALUES(end), status=VALUES(status), data=VALUES(data);
    `;

    msgReport = {
        topic: sql,
        payload: { truck_id: truckId, size: size, status: finalStatus }
    };

    state.batch_info = null;
    state.status_list = [];
    flow.set('active_batch', null);
}

// ====================================================
// FUNGSI 2: MEMBUAT SUMMARY DENGAN WAKTU 'START' SAJA
// ====================================================
if (sensorCode && sensorCode.includes("0101")) {
    const valArus = val;

    if (timestamp - state.last_active_time >= TIME_3_HR && state.status !== "ACTIVE" && state.status !== "DETECTING") {
        state.truck_count = 0;
    }

    if (valArus >= MIN_ARUS) {
        state.last_active_time = timestamp;

        if (state.status === "IDLE" || state.status === "REST" || state.status === "DROPPED") {
            if (state.status === "DROPPED" && state.batch_info) calculateFinalStats();

            state.status = "DETECTING";
            state.truck_count += 1;
            state.truck_start_time = timestamp;
            state.history_arus = [valArus];
            state.status_list = [];
            node.status({ fill: "yellow", shape: "ring", text: "Mendeteksi Truck " + state.truck_count + "..." });
        }
        else if (state.status === "DETECTING") {
            state.history_arus.push(valArus);
            if (state.history_arus.length >= SAMPLE_LIMIT) {
                let sum = state.history_arus.reduce((a, b) => a + b, 0);
                let avg = sum / state.history_arus.length;

                let matchedStd = standards.find(std => avg >= std.i_min && avg <= std.i_max);
                if (!matchedStd && standards.length > 0) matchedStd = standards[0];

                let detectedSize = matchedStd ? matchedStd.chicken_size : "AYAM_KECIL";

                state.batch_info = {
                    truck_id: "Truck " + state.truck_count,
                    plant: plantCode,
                    size: detectedSize,
                    avg_weight: matchedStd ? matchedStd.weight_min + " - " + matchedStd.weight_max : "",
                    std: matchedStd ? {
                        v_min: matchedStd.v_min, v_max: matchedStd.v_max,
                        i_min: matchedStd.i_min, i_max: matchedStd.i_max,
                        f_min: matchedStd.f_min, f_max: matchedStd.f_max
                    } : { v_min: 0, v_max: 0, i_min: 0, i_max: 0, f_min: 0, f_max: 0 },
                    start_time: state.truck_start_time
                };

                flow.set('active_batch', state.batch_info);
                state.status = "ACTIVE";

                // BIKIN SUMMARY AWAL (TANPA END TIME)
                let std = state.batch_info.std;
                let ccpUuid = msg.ccp?.uuid || msg.ccp_uuid || "674ad6bf-7d58-407f-9f87-8f4f3d2afe92";
                let startTime = toSQLTime(state.truck_start_time);

                let initialJsonData = JSON.stringify({
                    truck_id: state.batch_info.truck_id,
                    chicken_size: detectedSize,
                    avg_weight: state.batch_info.avg_weight,
                    eval_summary: "ONGOING",
                    v_min: std.v_min, v_max: std.v_max,
                    i_min: std.i_min, i_max: std.i_max,
                    f_min: std.f_min, f_max: std.f_max
                });

                let startSql = `
                    INSERT INTO sensor_cycle 
                    (project_code, sensor_code, production_date, cycle, start, end, status, data)
                    VALUES 
                    ('${ccpUuid}', 'STUNNER_SUMMARY', CURDATE(), '${state.batch_info.truck_id}', '${startTime}', NULL, 'ONGOING', '${initialJsonData}')
                    ON DUPLICATE KEY UPDATE status=VALUES(status), data=VALUES(data);
                `;
                node.send([null, { payload: state.batch_info }, { topic: startSql }]);

                node.status({ fill: "green", shape: "dot", text: state.batch_info.truck_id + " | " + detectedSize + " (" + avg.toFixed(3) + "A)" });
            }
        }
        else if (state.status === "ACTIVE") {
            state.history_arus.push(valArus);
        }
    }
    else {
        if (state.status === "ACTIVE" || state.status === "DETECTING") {
            state.status = "DROPPED";
            state.drop_start_time = timestamp;
        }
        else if (state.status === "DROPPED") {
            let dropDuration = timestamp - state.drop_start_time;
            if (dropDuration >= TIME_15_SEC) {
                if (state.batch_info || (state.truck_count > 0 && state.history_arus.length > 0)) calculateFinalStats();
                state.status = "IDLE";
                node.status({ fill: "grey", shape: "dot", text: "IDLE (Tunggu Truck)" });
            }
        }
        else if (state.status === "IDLE") {
            let idleDuration = timestamp - state.drop_start_time;
            if (idleDuration >= TIME_2_MIN && idleDuration < TIME_3_HR) {
                state.status = "REST";
                node.status({ fill: "blue", shape: "ring", text: "Istirahat (> 2 Menit)" });
            }
        }
    }
}

if (state.status === "ACTIVE" && state.batch_info) {
    msgToEvaluator = RED.util.cloneMessage(msg);
    msgToEvaluator.batch_info = state.batch_info;
}

flow.set("stunner_state", state);
return [msgToEvaluator, msgToUI, msgReport];

const activeBatch = flow.get('active_batch');

if (!activeBatch) {
    node.status({ fill: "grey", shape: "ring", text: "Idle - Tunggu Batch Start" });
    return null;
}

const sensorCode = msg.sensor_code || "";
const val = Number(msg.value) || 0;
const timestamp = msg.timestamp || new Date();
const ccpUuid = msg.ccp?.uuid || "674ad6bf-7d58-407f-9f87-8f4f3d2afe92";

const std = activeBatch.std;
let status = "OK";

// 1. Siapkan kerangka dasar JSON
let cycleDataObj = {
    truck_id: activeBatch.truck_id,
    chicken_size: activeBatch.size,
    avg_weight: activeBatch.avg_weight,
    last_val: val,
    eval_status: status // Akan diupdate di bawah
};

// 2. Evaluasi status & Sisipkan threshold sesuai kode sensor
if (sensorCode.includes("0301")) { // TEGANGAN
    if (val < std.v_min) status = "UNDER_STUNNED";
    else if (val > std.v_max) status = "OVER_STUNNED";

    // Masukkan threshold tegangan ke JSON
    cycleDataObj.v_min = std.v_min;
    cycleDataObj.v_max = std.v_max;

} else if (sensorCode.includes("0101")) { // ARUS
    if (val < std.i_min) status = "UNDER_STUNNED";
    else if (val > std.i_max) status = "OVER_STUNNED";

    // Masukkan threshold arus ke JSON
    cycleDataObj.i_min = std.i_min;
    cycleDataObj.i_max = std.i_max;

} else if (sensorCode.includes("0501")) { // FREKUENSI
    if (val < std.f_min) status = "UNDER_STUNNED";
    else if (val > std.f_max) status = "OVER_STUNNED";

    // Masukkan threshold frekuensi ke JSON
    cycleDataObj.f_min = std.f_min;
    cycleDataObj.f_max = std.f_max;
}

// Update eval_status akhir ke dalam objek JSON
cycleDataObj.eval_status = status;

// ---------------------------------------------------------
// SIMPAN STATUS KE STATE (UNTUK AKUMULASI STATUS AKHIR TRUCK)
// ---------------------------------------------------------
let currentState = flow.get("stunner_state") || {};
if (!currentState.status_list) {
    currentState.status_list = [];
}
currentState.status_list.push(status);
flow.set("stunner_state", currentState);
// ---------------------------------------------------------

const sqlMachine = `
INSERT INTO sensor_machine (project_code, sensor_code, value, cycle, timestamp)
VALUES ('${ccpUuid}', '${sensorCode}', '${val}', '${activeBatch.truck_id}', '${timestamp}');
`;

// Stringify objek JSON yang sudah disisipkan threshold spesifik
const cycleDataStr = JSON.stringify(cycleDataObj);

const sqlCycle = `
INSERT INTO sensor_cycle (project_code, sensor_code, production_date, cycle, status, data)
VALUES ('${ccpUuid}', '${sensorCode}', CURDATE(), '${activeBatch.truck_id}', '${status}', '${cycleDataStr}')
ON DUPLICATE KEY UPDATE status=VALUES(status), data=VALUES(data);
`;

let msgMachine = RED.util.cloneMessage(msg);
msgMachine.topic = sqlMachine;

let msgCycle = RED.util.cloneMessage(msg);
msgCycle.topic = sqlCycle;

node.status({
    fill: status === "OK" ? "green" : "red",
    shape: "dot",
    text: activeBatch.truck_id + " | " + sensorCode + ": " + val + " (" + status + ")"
});

return [msgMachine, msgCycle];

if (msg.error) {
    node.error("GAGAL membuat tabel", msg.error);
    return msg;
}

node.warn("BERHASIL menjalankan query database");

msg.payload = {
    status: "success",
    query: msg.topic,
    result: msg.payload
};

return msg;
